def final_counter_value(operations):
    """
    Computes the final value of a counter starting at 0 after performing the given operations.

    Parameters:
    operations (list of str): List of operations to perform, where each operation is 
                              one of "+", "-", "++", "--".

    Returns:
    int: The final value of the counter.
    """
    counter = 0
    for operation in operations:
        if operation == "+":
            counter += 1
        elif operation == "-":
            counter -= 1
        elif operation == "++":
            counter += 2
        elif operation == "--":
            counter -= 2
    return counter
